import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import Calculator from './components/Calculator';

function App() {
  return (
    <Router>
      <Switch>
        <Route path='/' component={Calculator} />
      </Switch>
    </Router>
  );
}

export default App;

from rest_framework.decorators import api_view
from rest_framework.response import Response
from rest_framework import status
import sympy as sp
import html

@api_view(['POST'])
def calculate(request):
    expression = request.data.get('expression')
    if not expression:
        return Response({'error': 'No expression provided'}, status=status.HTTP_400_BAD_REQUEST)
    try:
        result = sp.sympify(expression).evalf()
        return Response({'result': result}, status=status.HTTP_200_OK)
    except Exception as e:
        return Response({'error': html.escape('Invalid expression: ' + str(e))}, status=status.HTTP_400_BAD_REQUEST)

import React from 'react';

const Button = ({ value, onClick }) => {
  return (
    <button onClick={() => onClick(value)}>{value}</button>
  );
};

export default Button;

import React, { useState } from 'react';
import Button from './Button';
import axios from 'axios';

const Calculator = () => {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleButtonClick = (value) => {
    if (value === '=') {
      handleCalculate();
    } else {
      setInput(input + value);
      setError('');
    }
  };

  const handleCalculate = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.post('/api/calculate', { expression: input });
      setResult(response.data.result);
    } catch (error) {
      setError('Invalid expression');
      setResult('');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className='calculator'>
      <div className='display'>{loading ? <span className='spinner'>Loading...</span> : (result || input)}</div>
      {error && <div className='error'>{error}</div>}
      <div className='buttons'>
        {['1', '2', '3', '+', '4', '5', '6', '-', '7', '8', '9', '*', '0', '=', '/'].map((value) => (
          <Button key={value} value={value} onClick={handleButtonClick} />
        ))}
      </div>
    </div>
  );
};

export default Calculator;

